public static string ToHex(string input) {
    byte[] bytes = Encoding.Default.GetBytes(input);
    StringBuilder sb = new StringBuilder();
    foreach (byte b in bytes) sb.AppendFormat("{0:X2}", b);
    return sb.ToString();
}

